from pathlib import Path
from playwright.sync_api import sync_playwright
out=Path(__file__).parent/'screenshots'
out.mkdir(exist_ok=True)
css='''
*{box-sizing:border-box}body{margin:0;background:#081320;color:#f0f6ff;font:16px Arial,sans-serif}
.layout{display:flex;min-height:900px}.side{width:266px;padding:32px 22px;background:#0d1b2a;border-right:1px solid #263953}
.brand{font-size:20px;font-weight:800;letter-spacing:-.5px;margin:0 0 44px}.brand b{color:#62dec7}
.nav{padding:15px 16px;border-radius:12px;margin:7px 0;color:#a8bbd3;font-size:15px}.selected{background:#1b344b;color:white;font-weight:700;border-left:3px solid #63dec3}
.sidebottom{margin-top:290px;border:1px solid #33465c;border-radius:12px;padding:16px;background:#142538;font-size:13px;color:#afc1d5;line-height:1.8}
.main{flex:1;padding:36px 55px 50px;max-width:1320px}.eyebrow{font-size:13px;letter-spacing:2px;text-transform:uppercase;color:#64dfcc;font-weight:800;margin-bottom:10px}
.hero{background:linear-gradient(112deg,#122f4c,#173756 54%,#282951);border:1px solid #345a70;border-radius:19px;padding:34px 40px;display:flex;justify-content:space-between;align-items:center}
.hero h1{font-size:35px;margin:8px 0 10px;letter-spacing:-1px}.hero p{color:#c0d0e4;font-size:17px;margin:0}.heroicon{font-size:75px;opacity:.85}
.h{font-size:23px;font-weight:800;margin:34px 0 17px;letter-spacing:-.4px}.cards{display:flex;gap:18px}.card{flex:1;background:#111f30;border:1px solid #293d55;border-radius:14px;padding:22px 22px 25px;min-height:121px}
.label{color:#93a8c3;font-size:14px;margin-bottom:15px}.value{font-size:27px;font-weight:800}.accent{color:#6ee6d4}
.panel{background:#102034;border:1px solid #293e56;border-radius:16px;padding:27px;margin-top:18px}.hint{color:#b1c4dc;font-size:15px;line-height:1.7}
.bar{height:16px;border-radius:12px;background:#30465c;overflow:hidden;display:flex}.rf{background:#69d2c7;width:50%}.xg{background:#9c91ff;flex:1}
.steps{display:flex;gap:12px}.step{flex:1;background:#14283c;border:1px solid #2e4660;border-radius:13px;padding:18px 15px;color:#d9e8f6;font-weight:600}.step small{display:block;color:#6bddcf;letter-spacing:1px;margin-bottom:10px}
.note{border:1px solid #886e33;background:#302a1b;color:#edce83;padding:14px 18px;border-radius:11px;font-size:14px;margin-top:16px}
.table{width:100%;border-collapse:collapse;margin-top:12px;text-align:left}.table th{background:#193047;color:#90b5ca;padding:20px;font-size:14px}.table td{padding:23px 20px;border-bottom:1px solid #284058;color:#e4eefb}.muted{color:#88a0b8}
.pill{display:inline-block;background:#253c4b;border-radius:20px;padding:8px 13px;color:#79e4d5;font-size:12px;font-weight:700}
.upload{border:2px dashed #41617b;border-radius:15px;padding:48px;text-align:center;background:#122539;font-size:21px;font-weight:700}.foot{font-size:13px;color:#9caec6;margin-top:22px}.watermark{position:absolute;right:26px;bottom:15px;color:#c2cedd;font-size:12px;letter-spacing:.5px;background:#1e2c42;border:1px solid #607389;padding:7px 12px;border-radius:8px}
'''
def shell(selected,body):
 nav=''.join(f'<div class="nav {"selected" if name==selected else ""}">{icon} &nbsp; {name}</div>' for name,icon in [('Overview','◈'),('Model Comparison','▥'),('Predict Games','◇'),('About Project','ⓘ')])
 return f'''<!doctype html><html><head><meta charset="utf-8"><style>{css}</style></head><body><div class="layout"><aside class="side"><div class="brand">🎮 &nbsp;GAME<b>INSIGHT</b></div><div class="eyebrow">WORKSPACE</div>{nav}<div class="sidebottom">◉ &nbsp; MODEL STATUS<br><b style="color:#e1c179">Not trained / not loaded</b><br>Real evaluation metrics appear after model export.</div></aside><main class="main">{body}</main></div><div class="watermark">ILLUSTRATIVE UI PREVIEW · NOT LIVE MODEL RESULTS</div></body></html>'''
hero='''<div class="eyebrow">MACHINE LEARNING DASHBOARD</div><div class="hero"><div><span class="pill">BINARY CLASSIFICATION</span><h1>Android Games · ML Studio</h1><p>Understand, predict, and evaluate game success.</p></div><div class="heroicon">🎮</div></div>'''
overview=hero+'''<div class="h">Project at a glance</div><div class="cards"><div class="card"><div class="label">Prediction target</div><div class="value">is_hit_game</div></div><div class="card"><div class="label">Base models</div><div class="value">02</div></div><div class="card"><div class="label">Ensemble method</div><div class="value accent">Soft Voting</div></div><div class="card"><div class="label">Hyperparameter tuning</div><div class="value" style="font-size:21px">RandomizedSearchCV</div></div></div><div class="h">End-to-end ML workflow</div><div class="steps"><div class="step"><small>01 — EXPLORE</small>Dataset & class balance</div><div class="step"><small>02 — TRAIN</small>RF + XGBoost</div><div class="step"><small>03 — OPTIMIZE</small>Cross-validation</div><div class="step"><small>04 — EVALUATE</small>F1 / Recall / PR-AUC</div></div><div class="panel"><div class="h" style="margin:0 0 13px">Ensemble prediction architecture</div><div class="hint">Pre-launch game features → preprocessing → two classifiers → weighted average probability → decision threshold</div><div class="bar" style="margin-top:22px"><div class="rf"></div><div class="xg"></div></div><div style="display:flex;justify-content:space-between;margin-top:14px;color:#b8cde1;font-size:14px"><span>● Random Forest</span><span>● XGBoost</span></div></div><div class="note">⚠  No model results are shown until training and evaluation have been completed.</div>'''
compare=hero+'''<div class="h">Model evaluation framework</div><div class="cards"><div class="card"><div class="label">Primary evaluation</div><div class="value accent">F1 · Hit class</div></div><div class="card"><div class="label">Ranking performance</div><div class="value">PR-AUC</div></div><div class="card"><div class="label">Class imbalance</div><div class="value">Stratified CV</div></div></div><div class="panel"><div class="h" style="margin:0 0 9px">Comparison table</div><div class="hint">Metrics are populated from the held-out test set once the notebook finishes training.</div><table class="table"><tr><th>CLASSIFIER</th><th>F1 (HIT)</th><th>RECALL</th><th>PRECISION</th><th>PR-AUC</th></tr><tr><td><b>Random Forest</b></td><td class="muted">Pending</td><td class="muted">Pending</td><td class="muted">Pending</td><td class="muted">Pending</td></tr><tr><td><b>XGBoost</b></td><td class="muted">Pending</td><td class="muted">Pending</td><td class="muted">Pending</td><td class="muted">Pending</td></tr><tr><td><b>Soft Voting</b> &nbsp;<span class="pill">ENSEMBLE</span></td><td class="muted">Pending</td><td class="muted">Pending</td><td class="muted">Pending</td><td class="muted">Pending</td></tr></table></div><div class="note">⚠  This is a layout preview — the application will never invent evaluation scores.</div>'''
predict=hero+'''<div class="h">Predict game success</div><div class="cards"><div class="card"><div class="label">Prediction engine</div><div class="value accent">Soft Voting</div></div><div class="card"><div class="label">Input format</div><div class="value">CSV</div></div><div class="card"><div class="label">Output</div><div class="value">Hit / Not Hit</div></div></div><div class="panel"><div class="h" style="margin:0 0 9px">Batch prediction</div><p class="hint">Upload a dataset containing the same game attributes used in training to generate predictions and export results.</p><div class="upload">☁<br><br>Drop a CSV file here<br><span class="muted" style="font-size:15px;font-weight:400">or browse from your computer</span><div style="margin:23px auto 0;display:inline-block;background:#69d9c9;color:#072333;padding:13px 24px;border-radius:9px;font-size:15px">Browse files</div></div><p class="foot">Expected output: Random Forest probability · XGBoost probability · Voting probability · Predicted Hit</p></div><div class="note">⚠  Predictions require a trained and exported model bundle. This preview is non-interactive.</div>'''
with sync_playwright() as p:
 browser=p.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 for idx,(name,html) in enumerate([('dashboard',overview),('model-comparison',compare),('prediction',predict)],1):
  page=browser.new_page(viewport={'width':1600,'height':900},device_scale_factor=1)
  page.set_content(shell(['Overview','Model Comparison','Predict Games'][idx-1],html))
  path=out/f'{idx:02d}-{name}-preview.png'
  page.screenshot(path=str(path),full_page=True)
  print(path)
  page.close()
 browser.close()
